import{_ as e,o as a,c as d,a2 as n}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"5. Executed Test Baseline","description":"","frontmatter":{},"headers":[],"relativePath":"en/publications/implementation-case-i0.6/part-02.md","filePath":"en/publications/implementation-case-i0.6/part-02.md","lastUpdated":1786085052000}'),i={name:"en/publications/implementation-case-i0.6/part-02.md"};function r(s,t,o,c,l,p){return a(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="_5-executed-test-baseline" tabindex="-1">5. Executed Test Baseline <a class="header-anchor" href="#_5-executed-test-baseline" aria-label="Permalink to &quot;5. Executed Test Baseline&quot;">​</a></h1><p>All primary runs were author-executed. A PASS in the Reference Reader track is never copied into the product track.</p><table tabindex="0"><thead><tr><th>Track</th><th style="text-align:right;">Result</th><th style="text-align:right;">Exit</th><th>Interpretation</th></tr></thead><tbody><tr><td>S0.5 Reference Reader</td><td style="text-align:right;">14 passed</td><td style="text-align:right;">0</td><td>Executable interpretation over synthetic fixtures</td></tr><tr><td>FCoP v3.2.5 full suite</td><td style="text-align:right;">1,222 passed, 3 failed, 2 skipped</td><td style="text-align:right;">1</td><td>Product assertions include three retained failures</td></tr><tr><td>FCoP library CI subset</td><td style="text-align:right;">907 passed, 1 failed</td><td style="text-align:right;">1</td><td><code>parent</code> persistence/readback gap</td></tr><tr><td>FCoP MCP CI subset</td><td style="text-align:right;">78 passed, 2 failed</td><td style="text-align:right;">1</td><td>report lifecycle and tool-surface snapshot gaps</td></tr><tr><td>CodeFlowMu Protocol</td><td style="text-align:right;">8/8</td><td style="text-align:right;">0</td><td>Five valid and three expected-invalid fixtures</td></tr><tr><td>CodeFlowMu Runtime</td><td style="text-align:right;">1,420 passed, 1 failed, 1 skipped</td><td style="text-align:right;">1</td><td>One retained human-prompt contract mismatch</td></tr><tr><td>CodeFlowMu Shell</td><td style="text-align:right;">770/770</td><td style="text-align:right;">0</td><td>Full isolated Shell snapshot</td></tr><tr><td>Protocol / Runtime / Shell type checks</td><td style="text-align:right;">all passed</td><td style="text-align:right;">0</td><td>Static checks only</td></tr><tr><td>WP-13 V3 validation</td><td style="text-align:right;">passed</td><td style="text-align:right;">0</td><td>23/23 internal hashes and structured-data checks</td></tr></tbody></table><p>Two FCoP stdout files were normalized into decodable UTF-8 and contain U+FFFD replacement characters. Counts, exit codes, and identified failure names remain intact, but the package does not claim byte-for-byte preservation of the original process output.</p><h1 id="_6-c01–c14-product-results" tabindex="-1">6. C01–C14 Product Results <a class="header-anchor" href="#_6-c01–c14-product-results" aria-label="Permalink to &quot;6. C01–C14 Product Results&quot;">​</a></h1><table tabindex="0"><thead><tr><th>ID</th><th>S0.5 criterion</th><th style="text-align:right;">Reader</th><th style="text-align:right;">Product</th><th>Product evidence boundary</th></tr></thead><tbody><tr><td>C01</td><td>Schema validation</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Selected positive and negative schema paths ran; the full canonical object surface did not.</td></tr><tr><td>C02</td><td>Primary carrier and immutability</td><td style="text-align:right;">PASS</td><td style="text-align:right;"><strong>FAIL</strong></td><td>FCoP <code>parent</code> was accepted on the write surface but not closed through persistence/readback and published surface snapshots.</td></tr><tr><td>C03</td><td>Duplicate identity</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Duplicate/conflict mechanisms exist; canonical product quarantine output is incomplete.</td></tr><tr><td>C04</td><td>Stream continuity and asynchronous progress</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Ordering and dependency mechanisms ran without a complete canonical partial-order graph.</td></tr><tr><td>C05</td><td>Role authority</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Role gates ran; complete S0.5 authority issue/judgment output did not.</td></tr><tr><td>C06</td><td>Lifecycle legality</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Lifecycle controls ran; the complete required three-valued canonical outputs did not.</td></tr><tr><td>C07</td><td>Separation of duties and human control</td><td style="text-align:right;">PASS</td><td style="text-align:right;"><strong>FAIL</strong></td><td>Human-control structure exists, but one mandatory prompt-contract assertion failed.</td></tr><tr><td>C08</td><td>Integrity tampering</td><td style="text-align:right;">PASS</td><td style="text-align:right;">NOT RUN</td><td>Adjacent hashes do not substitute for the product criterion.</td></tr><tr><td>C09</td><td>Missing reference</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Failure visibility exists; canonical <code>undetermined</code> propagation is incomplete.</td></tr><tr><td>C10</td><td>Prohibited cycle</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>Local cycle detection passed; canonical affected-subgraph isolation did not run.</td></tr><tr><td>C11</td><td>Deterministic reconstruction</td><td style="text-align:right;">PASS</td><td style="text-align:right;">NOT RUN</td><td>Only the Reference Reader performed the required permutation-equivalent reconstruction.</td></tr><tr><td>C12</td><td>Conflict preservation</td><td style="text-align:right;">PASS</td><td style="text-align:right;">NOT RUN</td><td>Adjacent conflict mechanisms exist; the exact product criterion did not run.</td></tr><tr><td>C13</td><td>Recovery</td><td style="text-align:right;">PASS</td><td style="text-align:right;">PARTIAL</td><td>File-fact recovery is demonstrated; complete fresh-reader reconstruction is not.</td></tr><tr><td>C14</td><td>Terminal-history preservation</td><td style="text-align:right;">PASS</td><td style="text-align:right;"><strong>PASS</strong></td><td>Product tests support retained terminal history and authorization behavior.</td></tr></tbody></table><p>Product aggregate: <strong>1 PASS / 8 PARTIAL / 3 NOT RUN / 2 FAIL</strong>. The aggregate is not conformant.</p><h1 id="_7-retained-failure-analysis" tabindex="-1">7. Retained Failure Analysis <a class="header-anchor" href="#_7-retained-failure-analysis" aria-label="Permalink to &quot;7. Retained Failure Analysis&quot;">​</a></h1><h2 id="_7-1-c02-—-fcop-parent-closure" tabindex="-1">7.1 C02 — FCoP <code>parent</code> closure <a class="header-anchor" href="#_7-1-c02-—-fcop-parent-closure" aria-label="Permalink to &quot;7.1 C02 — FCoP \`parent\` closure&quot;">​</a></h2><p>The FCoP failures are not treated as a failure of the FCoP protocol definition itself. They show a reference-implementation release-consistency gap: the optional <code>parent</code> field appears on the current API/MCP surface, but round-trip persistence/readback and stored public-surface snapshots are not all synchronized. Until the same object survives the complete write–persist–read path and surface snapshots are updated under release control, C02 remains FAIL.</p><h2 id="_7-2-c07-—-human-adjudication-prompt-contract" tabindex="-1">7.2 C07 — human-adjudication prompt contract <a class="header-anchor" href="#_7-2-c07-—-human-adjudication-prompt-contract" aria-label="Permalink to &quot;7.2 C07 — human-adjudication prompt contract&quot;">​</a></h2><p>The CodeFlowMu Runtime test expected either <code>需 ADMIN 人工裁定</code> or <code>需人工裁定</code>. The actual readable output was <code>需 ADMIN/PM 人工裁定</code>. Structured fields remained valid—<code>decision=needs_human</code>, <code>fact_check_verdict=needs_admin</code>, and <code>awaiting_pm_decision=true</code>—and lifecycle did not advance.</p><p>The failure is therefore a wording-contract mismatch, not Chinese encoding damage. The raw mandatory assertion failed, so C07 remains FAIL until the product and test owners decide whether <code>ADMIN/PM</code> is an intended product contract or the test expectation is stale, make the corresponding change, and rerun the complete Runtime acceptance suite.</p><h1 id="_8-wp-13-multi-agent-evidence-gating-case" tabindex="-1">8. WP-13 Multi-Agent Evidence-Gating Case <a class="header-anchor" href="#_8-wp-13-multi-agent-evidence-gating-case" aria-label="Permalink to &quot;8. WP-13 Multi-Agent Evidence-Gating Case&quot;">​</a></h1><p>WP-13 asks whether a multi-agent governance chain can prevent an unverified completion claim from becoming an authoritative delivery fact. A DEV subexecution ended with completion-meaning language while exit status, tests, commit, and formal report were not all confirmed. PM checked persistent facts, withheld release, and did not dispatch QA. After tool recovery, DEV completed the same task, produced commit <code>609571dd…</code> and a formal report, and role-separated QA reran 27 tests, type checking, and diff checks successfully.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>completion-meaning claim</span></span>
<span class="line"><span>        ↓ persistent evidence incomplete</span></span>
<span class="line"><span>PM fact check → hold / do not release / do not dispatch QA</span></span>
<span class="line"><span>        ↓ same-task recovery</span></span>
<span class="line"><span>DEV commit + report</span></span>
<span class="line"><span>        ↓ separate role</span></span>
<span class="line"><span>QA rerun and report</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>candidate evidence for authorized decision</span></span></code></pre></div><p>At the first observation point, “WP-13 is complete” was neither established as <code>valid</code> nor proved <code>invalid</code>; the appropriate S0.5 analytical judgment was <code>undetermined</code>. This is a retrospective TMPA projection. The native application did not emit the complete canonical S0.5 Reader envelope.</p><p>The case demonstrates governance containment, role separation, same-task recovery, and evidence completion. It does not prove elimination of hallucinations, independent validation, terminal approval within the original snapshot, cryptographic provenance, or independently adopted TMPA conformance.</p><p>The V3 package records <code>runtime_bound: false</code>; its snapshot ends while TASK-019/020 are still <code>review / pending</code>. Gate C acceptance occurred later and remains a separate lifecycle fact. “DEV complete,” “QA pass,” “Gate C accept,” “done,” and “archive” must not be collapsed.</p>`,19)])])}const g=e(i,[["render",r]]);export{u as __pageData,g as default};
